CREATE TABLE IF NOT EXISTS playlist_imports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), playlist_id text NOT NULL, state text NOT NULL, title text, video_ids text[] NOT NULL DEFAULT '{}', task_id text, category_id uuid REFERENCES categories(id) ON DELETE SET NULL, visible boolean NOT NULL DEFAULT false, error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(playlist_id));
DO $$ BEGIN ALTER TABLE playlist_imports ADD CONSTRAINT playlist_import_state_check CHECK (state IN ('EXTRACTING','READY','FAILED')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
